-- Subscripts written flat, swept bank-wide (70 cards).
--
-- Mikko found this on the buoyancy card: "Fb = ρfluid·Vdisp·g" reads as six
-- variables multiplied together, because none of the subscripts were marked up.
-- The renderer has understood k_(cat) notation since the subscript work in
-- lib/flashcards/cloze.ts; these cards were written flat.
--
-- Five earlier files in this directory each fixed one card of this same defect.
-- This is the sweep: generated by scripts/flashcards/fix-flat-subscripts.mjs,
-- and every edit verified to be notation-only. Strip the markup back off and
-- each card reads exactly as it did before, so no question has changed.
--
-- NO SCHEDULE RESET. Unlike the merge fixes, nothing here changes what a card
-- asks or how many blanks it has. Resetting would throw away real progress for
-- a change of typography.
--
-- Deliberately NOT changed: W = Fd, P = Fv, Q = Av, k = Ae^(-Ea/RT), Gm₁m₂/r².
-- Those are products, not subscripts. Same shape on the page, opposite meaning.

BEGIN;

-- Circuits: Ceq -> C_(eq)
UPDATE public.flashcards SET cloze_text = 'Capacitors in series combine as {{c1::1/C_(eq) = 1/C₁ + 1/C₂ + …}}.' WHERE id = '06eb6c2b-a8dd-45e9-ac03-00853f581e9d';

-- Nonenzymatic Protein Function and Protein Analysis: Gq -> G_(q)
UPDATE public.flashcards SET cloze_text = 'In G_(q)-coupled receptor signaling, {{c1::phospholipase C}} cleaves PIP₂ into two second messengers: {{c2::DAG}} (activates PKC) and {{c2::IP₃}} (triggers Ca²⁺ release from the ER).' WHERE id = '0d203e8b-7fd7-4457-9443-6918a30bf02c';

-- Circuits: Ceq -> C_(eq)
UPDATE public.flashcards SET cloze_text = 'Capacitors in parallel combine as {{c1::C_(eq) = C₁ + C₂ + …}}.' WHERE id = '0e8ef1c7-33c4-48df-8a99-dda701d712a6';

-- Acids and Bases: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'Two classic MCAT buffers: acetic acid + sodium acetate (an {{c1::acid buffer}}, pK_(a) ≈ 4.76); ammonia + ammonium chloride (a {{c1::basic buffer}}).' WHERE id = '12a05f4c-8ca2-4b4a-91df-bb0872013ab6';

-- Atomic and Nuclear Phenomena: Kmax -> K_(max)
UPDATE public.flashcards SET cloze_text = 'The maximum kinetic energy of an ejected electron is {{c1::K_(max) = hf − W}}: the photon''s energy minus the energy spent {{c2::escaping the metal}}.' WHERE id = '195200b4-5d0a-494d-a4d9-4075b701e322';

-- Thermodynamics: Cp -> C_(p), Cv -> C_(v)
UPDATE public.flashcards SET cloze_text = 'For a gas, molar heat capacity C_(p) (constant pressure) is {{c1::greater than}} C_(v) (constant volume) because some added heat does {{c1::expansion work (PΔV)}} rather than raising temperature.' WHERE id = '27450c5e-0943-4ce3-a977-1745bdc1344d';

-- Nitrogen and Phosphorus Containing Compounds: pKa -> pK_(a) (2x)
UPDATE public.flashcards SET cloze_text = 'Phosphate is an excellent biological buffer because its pK_(a) values span a wide pH range, and the {{c1::pK_(a)₂ ≈ 7.20}} sits very close to physiological pH (~7.4).' WHERE id = '2c0a10b3-70de-4bb7-b314-55b1d20cb4bf';

-- Electrochemistry: E°(cell) -> E°_(cell)
UPDATE public.flashcards SET cloze_text = 'The {{c1::n}} in ΔG° = −nFE°_(cell) represents the number of {{c2::electrons}} transferred per balanced redox equation; balancing the half-reactions correctly is essential for the right value of n.' WHERE id = '312ffba8-3c4f-4e33-ace1-d790c6cb2c03';

-- The Gas Phase: χᵢ -> χ_(i), nᵢ -> n_(i)
UPDATE public.flashcards SET cloze_text = 'The mole fraction of component i is χ_(i) = {{c1::n_(i) / n_(total)}}.' WHERE id = '31d8f65e-5bbc-484d-91bf-f944cccf43fc';

-- Circuits: Req -> R_(eq)
UPDATE public.flashcards SET cloze_text = 'For resistors in parallel, the equivalent resistance comes from {{c1::1/R_(eq) = 1/R₁ + 1/R₂ + …}}.' WHERE id = '32f55bda-e7dd-41a8-9ae3-0af8c67e2e84';

-- The Gas Phase: urms -> u_(rms)
UPDATE public.flashcards SET cloze_text = 'The root-mean-square speed of gas molecules is u_(rms) = {{c1::√(3RT/M)}}, where M is the molar mass in kg/mol.' WHERE id = '348844b6-3b8d-452a-91f3-53ca5b2dc360';

-- Solutions: ΔTb -> ΔT_(b), ΔTf -> ΔT_(f)
UPDATE public.flashcards SET cloze_text = 'Boiling-point elevation ΔT_(b) and freezing-point depression ΔT_(f) require concentration as {{c1::molality}}, while Raoult''s law requires {{c1::mole fraction χ}}.' WHERE id = '3980df93-3165-4b1f-aae1-2b580a0fba8d';

-- Nitrogen and Phosphorus Containing Compounds: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'The α-carbon between the two ester {{c2::carbonyl}}s of phthalimidomalonic ester is acidic (pK_(a) ≈ {{c1::13}}) because the resulting enolate is stabilized by both adjacent {{c2::carbonyl}} groups.' WHERE id = '39f4f76d-f447-41b0-8eb2-49f21aff1f78';

-- Solutions: χsolvent -> χ_(solvent), P°solvent -> P°_(solvent)
UPDATE public.flashcards SET cloze_text = 'With only nonvolatile solutes, Raoult''s law gives a solution''s vapor pressure as P = {{c1::χ_(solvent) × P°_(solvent)}}.' WHERE id = '3b8215ab-3df9-4867-9652-41dd5bd61291';

-- Energy, Work & Simple Machines: Ug -> U_(g)
UPDATE public.flashcards SET cloze_text = 'Gravitational potential energy near Earth''s surface is {{c1::U_(g) = mgh}}, where m is mass, g is the acceleration due to gravity (≈ 9.8 m/s²), and h is the {{c2::height}} above a chosen reference level (the datum).' WHERE id = '3be96694-994f-4700-8496-af65827174ac';

-- Thermochemistry: ΔG°f -> ΔG°_(f) (2x)
UPDATE public.flashcards SET cloze_text = 'The standard free energy change of reaction is ΔG°ᵣₓₙ = {{c1::Σ ΔG°_(f)(products) − Σ ΔG°_(f)(reactants)}}.' WHERE id = '3c2022b0-126b-4634-973a-5761cdb3607e';

-- Bioenergetics and Regulation of Metabolism: Pi -> P_(i)
UPDATE public.flashcards SET cloze_text = 'ATP is regenerated from ADP + P_(i) through two mechanisms: {{c1::substrate-level phosphorylation}} (direct transfer in glycolysis and TCA) and {{c1::oxidative phosphorylation}} (driven by the proton motive force at ATP synthase).' WHERE id = '3d2a36a4-5580-49c5-9394-c6056fd23e18';

-- Amino Acids: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'Side-chain pK_(a) values of the acidic amino acids: {{c1::aspartate ≈ 3.65}} and {{c2::glutamate ≈ 4.25}}. Both side chains are fully deprotonated (negatively charged) at physiological pH (~7.4).' WHERE id = '3f8586ef-d79a-4ba7-a692-a6ee1667a11d';

-- Amino Acids, Peptides, and Proteins: pKa -> pK_(a) (3x)
UPDATE public.flashcards SET cloze_text = 'For an amino acid with an acidic side chain (Asp, Glu), the pI is the average of the {{c1::two lowest}} pK_(a) values: pI = (pK_(a),COOH + pK_(a),R)/2; this gives a {{c2::low}} pI.' WHERE id = '3f9349bc-d17b-4f7b-83b1-82725c7b3a64';

-- Electrochemistry: E°(cell) -> E°_(cell) (3x)
UPDATE public.flashcards SET cloze_text = 'When {{c1::K_(eq) > 1}}, E°_(cell) is {{c2::positive}}; when {{c1::K_(eq) < 1}}, E°_(cell) is {{c2::negative}}; when {{c1::K_(eq) = 1}}, E°_(cell) equals {{c2::zero}}.' WHERE id = '43024be0-12f8-41f5-b9a2-99abca85c9a9';

-- Acids and Bases: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'Polyprotic acids dissociate {{c1::stepwise}}, with each successive K_(a) {{c2::smaller}} than the one before it; H₃PO₄ has three distinct pK_(a) values.' WHERE id = '475b6f2a-eaac-4ce2-97a2-4a4a7cd627c6';

-- Solutions: Kf -> K_(f)
UPDATE public.flashcards SET cloze_text = 'The equilibrium constant for a metal ion binding ligands into a complex ion is the {{c1::formation (or stability)}} constant, abbreviated {{c1::K_(f)}}.' WHERE id = '480dfac0-ec75-4ea5-ad60-2f3dbc5c3e01';

-- Amino Acids, Peptides, and Proteins: pKa -> pK_(a) (3x)
UPDATE public.flashcards SET cloze_text = 'For an amino acid with a basic side chain (Lys, Arg, His), the pI is the average of the {{c1::two highest}} pK_(a) values: pI = (pK_(a),R + pK_(a),NH₃+)/2; this gives a {{c2::high}} pI.' WHERE id = '48a8f3bc-488c-46bc-93aa-25dea703cd7f';

-- Amino Acids, Peptides, and Proteins: pKa -> pK_(a) (3x)
UPDATE public.flashcards SET cloze_text = 'For an amino acid with a non-ionizable side chain, the pI is the {{c1::average}} of the α-amino and α-carboxyl pK_(a) values: pI = ({{c2::pK_(a),COOH + pK_(a),NH₃+}})/2.' WHERE id = '50d45996-f358-4f1d-8b28-5fa63b4250a3';

-- Analyzing Organic Reactions: pKa -> pK_(a) (2x)
UPDATE public.flashcards SET cloze_text = 'Strong acids typically have {{c1::pK_(a) < −2}} (they almost completely dissociate in water); weak organic acids typically have {{c1::pK_(a) between −2 and 20}}.' WHERE id = '52ea443d-8daf-40bf-89e2-ea89abe377d7';

-- Acids and Bases: pKa -> pK_(a) (2x)
UPDATE public.flashcards SET cloze_text = 'For a weak acid buffer, the Henderson-Hasselbalch equation is {{c1::pH = pK_(a) + log([A⁻]/[HA])}}, predicting buffer pH from the pK_(a) and concentration ratio.' WHERE id = '531107f6-e371-47a7-9731-cfb71e27d158';

-- Solutions: ΔTb -> ΔT_(b)
UPDATE public.flashcards SET cloze_text = 'For a nonvolatile solute, boiling-point elevation is ΔT_(b) = {{c1::i·K_(b)·m}}.' WHERE id = '5a07dafc-2c92-46c3-9f4a-f5b8620c99a8';

-- Nonenzymatic Protein Function and Protein Analysis: Tmax -> T_(max)
UPDATE public.flashcards SET cloze_text = 'Like enzymes, ion channels and other membrane transporters can show {{c1::saturation}} kinetics. Once every channel is occupied, the transport rate plateaus at a maximum called {{c2::T_(max)}}.' WHERE id = '6957feae-6872-48ba-91b2-cb08339025b2';

-- Acids and Bases: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'At the {{c1::half-equivalence point}}, exactly half of the weak acid has been neutralized, so [HA] = [A⁻] and {{c2::pH = pK_(a)}}.' WHERE id = '6c25adce-8f05-4f9b-bc84-942148c554da';

-- Fluids: Fg -> F_(g)
UPDATE public.flashcards SET cloze_text = 'A volume V of fluid with density ρ has weight F_(g) = {{c1::ρVg}}, where g is the gravitational acceleration.' WHERE id = '6e91f14e-6a33-41d2-9c08-ff2fee3a3348';

-- Amino Acids: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = '{{c1::Histidine}} stands out among the basic amino acids for having a side-chain pK_(a) near physiological pH (~6); this lets it act as a {{c2::proton acceptor or donor}} in enzyme active sites and as the buffering residue in {{c3::hemoglobin and other proteins}}.' WHERE id = '720f706c-a272-420d-99ba-927ed9cd2709';

-- Motion & Forces: Rₓ -> R_(x) (2x), Ry -> R_(y) (2x)
UPDATE public.flashcards SET cloze_text = 'After computing the resultant''s components, its magnitude is obtained from the {{c1::Pythagorean theorem}}: R = √(R_(x)² + R_(y)²). Its direction (the angle from the +x axis) is given by {{c2::θ = tan⁻¹(R_(y)/R_(x))}}.' WHERE id = '7513b03d-c427-40a3-9723-ff03c2971d10';

-- Amino Acids, Peptides, and Proteins: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'Near a pK_(a) value, an amino acid acts as a {{c1::buffer}}: adding more base produces only a small pH change because the deprotonation reaction absorbs the added hydroxide.' WHERE id = '7586c6e0-b52f-44e5-8b2d-18b59b0ba70a';

-- Solutions: Kf -> K_(f) (2x), ΔTf -> ΔT_(f)
UPDATE public.flashcards SET cloze_text = 'For a dilute solution, freezing-point depression is ΔT_(f) = {{c1::i·K_(f)·m}}, where K_(f) is the cryoscopic constant and m is molality.' WHERE id = '8144cda1-9cf7-4145-a771-bffedc675b63';

-- Motion & Forces: Fnet -> F_(net)
UPDATE public.flashcards SET cloze_text = 'Newton''s second law states that the net force on an object equals its mass times its acceleration: {{c1::F_(net) = ma}}. Because F and a are both vectors, they always point in the {{c2::same direction}}.' WHERE id = '8224a844-7297-4649-9265-9b8d86a6a431';

-- Acids and Bases: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'When the concentrations of conjugate base and weak acid are equal ([A⁻] = [HA]), the log term is zero and {{c1::pH = pK_(a)}}.' WHERE id = '82d672d3-7ca3-4121-9524-89d7077c87b0';

-- Electrochemistry: E°(cell) -> E°_(cell)
UPDATE public.flashcards SET cloze_text = 'The fundamental link between thermodynamics and electrochemistry is {{c1::ΔG° = −nFE°_(cell)}}, where n is moles of electrons transferred and F is Faraday''s constant.' WHERE id = '882a89eb-c7ff-45fe-9125-eaa450bca296';

-- The Musculoskeletal System: Pi -> P_(i)
UPDATE public.flashcards SET cloze_text = 'Once myosin heads bind actin, release of {{c1::P_(i) (inorganic phosphate)}} from the myosin head drives the {{c2::power stroke}}, pulling the thin filament toward the sarcomere center.' WHERE id = '8861788c-cd7a-4bf4-a984-26e8c92d70b4';

-- Amino Acids: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'Side-chain pK_(a) values of the basic amino acids: {{c1::lysine ≈ 10.5}}, {{c2::arginine ≈ 12.5}}, and {{c3::histidine ≈ 6.0}}. {{c1::Lysine}} and {{c2::arginine}} are essentially always protonated at physiological pH; {{c3::histidine}} straddles 7.4 and can be either form.' WHERE id = '8dba063f-312a-4123-9c13-5c842ffed692';

-- Acids and Bases: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'To estimate pX for a value (n × 10⁻ᵐ) on the MCAT: pX ≈ {{c1::m − 0.n}}. Example: pK_(a) for K_(a) = 1.8 × 10⁻⁵ is approximately {{c2::5 − 0.18 = 4.82}}.' WHERE id = '925e173e-12df-43e7-946b-4a2ccdd543b5';

-- Motion & Forces: Rₓ -> R_(x), Aₓ -> A_(x), Bₓ -> B_(x), Ry -> R_(y), Ay -> A_(y), By -> B_(y)
UPDATE public.flashcards SET cloze_text = 'To add vectors by the component method: (1) resolve each vector into x- and y-components, (2) add the x-components separately and the y-components separately, (3) the resultant''s components are {{c1::R_(x) = A_(x) + B_(x)}} and {{c1::R_(y) = A_(y) + B_(y)}}.' WHERE id = '94a5254d-35e8-4573-97c2-2e34db7558ea';

-- Equilibrium: Kc -> K_(c), Kp -> K_(p)
UPDATE public.flashcards SET cloze_text = 'The equilibrium constant written with molar concentrations is {{c1::K_(c)}}, while the one written with partial pressures of gases is {{c2::K_(p)}}.' WHERE id = '94c521d8-a631-4bb9-afb5-723aad260a8d';

-- Acids and Bases: pKa -> pK_(a), pKb -> pK_(b)
UPDATE public.flashcards SET cloze_text = 'For a conjugate acid-base pair, {{c1::K_(a) × K_(b) = K_(w)}} = 1 × 10⁻¹⁴; equivalently, pK_(a) + pK_(b) = 14.' WHERE id = 'a6790f5d-5c79-4b3a-95f6-39056e1b3d83';

-- Bioenergetics and Regulation of Metabolism: Pi -> P_(i)
UPDATE public.flashcards SET cloze_text = 'ATP hydrolysis is highly exergonic because the products (ADP + P_(i)) are stabilized by {{c1::resonance}}, {{c1::ionization}}, and relief of {{c1::charge repulsion}} that exist in ATP itself.' WHERE id = 'a6bdba8e-9d0e-461c-934e-502470dde064';

-- Energy, Work & Simple Machines: Wnet -> W_(net), Ki -> K_(i), Kf -> K_(f)
UPDATE public.flashcards SET cloze_text = 'The {{c1::work-energy theorem}} states that the net work done on an object by all forces equals its change in kinetic energy: {{c2::W_(net) = ΔK = K_(f) − K_(i)}}. This holds whether the forces involved are conservative or non-conservative.' WHERE id = 'a86d4cf8-6921-4b45-b717-993179d19ada';

-- Motion & Forces: Fg -> F_(g)
UPDATE public.flashcards SET cloze_text = 'Newton''s law of universal gravitation: every pair of masses attracts each other with a force {{c1::F_(g) = Gm₁m₂/r²}}, where {{c2::G = 6.67 × 10⁻¹¹ N·m²/kg²}} is the universal gravitational constant and r is the distance between the centers of the two masses.' WHERE id = 'aa98d149-5bd4-498b-bf07-3783beef5c79';

-- Analyzing Organic Reactions: pKa -> pK_(a) (2x)
UPDATE public.flashcards SET cloze_text = 'The {{c1::acid dissociation constant (K_(a))}} = {{c2::[H⁺][A⁻] / [HA]}}; {{c3::pK_(a) = −log(K_(a))}}, and a {{c4::lower pK_(a)}} means a stronger acid.' WHERE id = 'aacc1d5a-c25b-4612-8cc4-a97ebce3523c';

-- The Musculoskeletal System: Pi -> P_(i)
UPDATE public.flashcards SET cloze_text = 'Myosin then hydrolyzes the bound ATP to {{c1::ADP and P_(i)}}; this energy is used to {{c2::recock}} the myosin head into position for another cross-bridge cycle.' WHERE id = 'abbaa74b-64cd-4beb-a595-d81cd121354c';

-- Nitrogen and Phosphorus Containing Compounds: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'The three pK_(a) values of H₃PO₄, for loss of the first, second, and third proton, are approximately {{c1::2.15, 7.20, and 12.32}}.' WHERE id = 'b08b6ebd-6005-4fce-8dd3-cbf0f9eed0bc';

-- Electrochemistry: E°(cell) -> E°_(cell), E°(cathode) -> E°_(cathode), E°(anode) -> E°_(anode)
UPDATE public.flashcards SET cloze_text = 'The standard cell EMF (electromotive force) is calculated as {{c1::E°_(cell) = E°_(cathode) − E°_(anode)}}, using reduction potentials for both electrodes (do NOT flip the anode sign).' WHERE id = 'b1d1dbea-3bbb-4f82-b997-838ed4b55241';

-- Amino Acids, Peptides, and Proteins: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'The {{c1::pK_(a)}} of an ionizable group is the pH at which, on average, exactly half of the molecules of that species are {{c2::deprotonated}}.' WHERE id = 'b3ad53b7-5c77-4a02-bceb-e27e255149df';

-- Carbohydrate Metabolism II: Pi -> P_(i)
UPDATE public.flashcards SET cloze_text = '{{c1::Chemiosmotic coupling}} (Mitchell''s hypothesis) describes the direct link between the proton motive force and ATP synthesis: the chemical energy of the proton gradient drives {{c2::ADP + P_(i) → ATP}}.' WHERE id = 'b5bb5cec-e8b9-411f-881b-d2140824987f';

-- Energy, Work & Simple Machines: Wnet -> W_(net), Wnc -> W_(nc)
UPDATE public.flashcards SET cloze_text = 'The work-energy theorem (W_(net) = ΔK) relates net work to {{c1::kinetic energy only}}, not potential and not {{c2::total mechanical}} energy. By contrast, the broader energy-conservation principle (ΔE = W_(nc) when E = K + U) relates non-conservative work to {{c2::total mechanical}} energy.' WHERE id = 'b8069e98-a273-4f4b-90b7-ed4ffead0341';

-- Electrochemistry: E°(cell) -> E°_(cell) (2x)
UPDATE public.flashcards SET cloze_text = 'Galvanic cells have {{c1::negative ΔG°}} and {{c1::positive E°_(cell)}} (spontaneous); electrolytic cells have {{c1::positive ΔG°}} and {{c1::negative E°_(cell)}} (nonspontaneous).' WHERE id = 'b821a7a8-6deb-4a4e-af1c-3f7319a8ffff';

-- Fluids: Fb -> F_(b), ρfluid -> ρ_(fluid) (2x), Vdisp -> V_(disp) (2x)
UPDATE public.flashcards SET cloze_text = 'The buoyant force is F_(b) = {{c1::ρ_(fluid)·V_(disp)·g}}, where ρ_(fluid) is the fluid''s density, V_(disp) is the volume of fluid displaced, and g is the gravitational acceleration.' WHERE id = 'bc805ce1-7561-4a3b-8efc-a05a1f8e84af';

-- Energy, Work & Simple Machines: Wnc -> W_(nc)
UPDATE public.flashcards SET cloze_text = 'When {{c1::non-conservative}} forces act, mechanical energy is generally lost. The work done by {{c1::non-conservative}} forces equals the {{c2::change in total mechanical energy}}: W_(nc) = ΔE = ΔK + ΔU (typically negative when friction or drag dissipates energy).' WHERE id = 'bd932b52-10d8-4caf-ac55-76f6ca3eb1f3';

-- Nonenzymatic Protein Function and Protein Analysis: Gq -> G_(q)
UPDATE public.flashcards SET cloze_text = '{{c1::IP₃}} produced by the G_(q) pathway diffuses to the endoplasmic reticulum and opens calcium channels there, releasing stored {{c2::Ca²⁺}} into the cytosol as a second messenger.' WHERE id = 'bdfe5fcf-cea9-41ba-a5b7-3d9058084cfb';

-- Acids and Bases: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = '{{c1::Buffering capacity}} is the amount of acid or base a buffer can absorb before its pH changes significantly; it is greatest within {{c2::±1 pH unit}} of the pK_(a).' WHERE id = 'be9b5095-c38a-45d8-b4e0-7bd92f712946';

-- Electrochemistry: E°(cell) -> E°_(cell) (2x)
UPDATE public.flashcards SET cloze_text = 'ΔG° = −nFE°_(cell) = {{c1::−RT ln K_(eq)}}, so E°_(cell) and K_(eq) are linked: large K_(eq) → large positive E°.' WHERE id = 'c084856d-1f83-4e5f-b51d-ad038ea6b0b5';

-- Solutions: Kf -> K_(f) (2x), ΔTf -> ΔT_(f)
UPDATE public.flashcards SET cloze_text = 'K_(f) is ambiguous: in ΔT_(f) = i·K_(f)·m it is the solvent''s cryoscopic (freezing-point-depression) constant; in complex-ion equilibria it is the {{c1::formation (stability) constant}}.' WHERE id = 'c3162e2a-38ca-4a7c-a321-a214ea612e63';

-- Amino Acids, Peptides, and Proteins: pKa -> pK_(a) (3x)
UPDATE public.flashcards SET cloze_text = 'Every amino acid has at least two pK_(a) values: the α-carboxyl group near {{c1::pK_(a) ~2}} and the α-amino group near {{c2::pK_(a) ~9-10}}.' WHERE id = 'c429a022-c9bb-4830-8495-a8ade51e68e2';

-- Nonenzymatic Protein Function and Protein Analysis: Kd -> K_(d) (2x)
UPDATE public.flashcards SET cloze_text = 'The affinity of a protein for its ligand is measured by the {{c1::dissociation constant (K_(d))}}; a {{c2::smaller}} K_(d) corresponds to a higher binding affinity.' WHERE id = 'c6625c83-dca6-4e07-9c77-e7d8e5603327';

-- Light and Optics: mtotal -> m_(total)
UPDATE public.flashcards SET cloze_text = 'For lenses in combination, total magnification is found by {{c1::multiplying}} the individual magnifications: m_(total) = {{c1::m₁ × m₂ × …}}.' WHERE id = 'c73dee86-3e25-4e66-8a88-a327383d1b37';

-- Acids and Bases: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'Indicators are themselves weak acids or bases that change color when protonated/deprotonated; a good indicator has a {{c1::pK_(a)}} close to the expected equivalence point pH.' WHERE id = 'c7a855bd-4068-40ed-8a5b-f4ce6fcb268b';

-- Acids and Bases: pKb -> pK_(b)
UPDATE public.flashcards SET cloze_text = 'For a weak base buffer, the Henderson-Hasselbalch equation is {{c1::pOH = pK_(b) + log([BH⁺]/[B])}}, predicting buffer pOH similarly.' WHERE id = 'c8602e8c-3d27-40ec-bb37-18e9c1627335';

-- Amino Acids: pKa -> pK_(a)
UPDATE public.flashcards SET cloze_text = 'Standard backbone pK_(a) values shared by all {{c2::amino}} acids: the {{c1::α-carboxyl group ≈ 2.0}} and the {{c2::α-amino group ≈ 9 to 10}}. At physiological pH both are ionized, producing the zwitterionic form.' WHERE id = 'd62f0aed-b2b7-4150-95fe-75d12c25580c';

-- Circuits: Req -> R_(eq)
UPDATE public.flashcards SET cloze_text = 'For resistors in series, the equivalent resistance is {{c1::R_(eq) = R₁ + R₂ + R₃ + …}}.' WHERE id = 'dc92817e-705a-4f36-b898-b4a4612b06d9';

-- Motion & Forces: Fnet -> F_(net)
UPDATE public.flashcards SET cloze_text = 'Newton''s first law (the law of {{c1::inertia}}) states that an object maintains its current state of motion (at rest if at rest, in constant velocity if moving) unless a {{c2::net external force}} changes it. Equivalently, {{c3::F_(net) = 0 implies a = 0}}.' WHERE id = 'f41dff99-fefd-4e71-a3af-8265336a9a38';

-- Thermochemistry: ΔG°f -> ΔG°_(f)
UPDATE public.flashcards SET cloze_text = 'By definition, the standard free energy of formation ΔG°_(f) of an element in its standard state equals {{c1::zero}}.' WHERE id = 'faeac545-7ba8-4fee-8421-6cbb4b6a849f';

-- Amino Acids, Peptides, and Proteins: pKa -> pK_(a) (2x)
UPDATE public.flashcards SET cloze_text = 'When the {{c1::pH}} is below an ionizable group''s pK_(a), the group is mostly {{c2::protonated}}; when pH is above the pK_(a), it is mostly {{c2::deprotonated}}.' WHERE id = 'fdd00cbc-7038-4b17-9070-af01df89f3ba';

COMMIT;
